import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"51. From Source to Executable: The Compilation Pipeline","description":"The Little Book of C — 51. From Source to Executable: The Compilation Pipeline","frontmatter":{"title":"51. From Source to Executable: The Compilation Pipeline","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Compilation and Build]","description":"The Little Book of C — 51. From Source to Executable: The Compilation Pipeline","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"51","sidebarWeight":"51","lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline.md","filePath":"posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/en-US/06-Compilation and Build/051-From Source to Executable The Compilation Pipeline.md"};function i(l,e,p,c,d,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/051-From Source to Executable The Compilation Pipeline)</p><p>Every time you run</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>you’re launching a complex, multi-stage process that transforms human-readable C code into a machine-executable binary. Understanding this compilation pipeline is the heart of becoming a real systems programmer.</p><p>Let’s unpack what happens between your<code>.c</code> file and the final executable.</p><h4 id="step-1-the-four-stages" tabindex="-1">Step 1. The Four Stages <a class="header-anchor" href="#step-1-the-four-stages" aria-label="Permalink to &quot;Step 1. The Four Stages&quot;">​</a></h4><p>A C compiler (like<code>gcc</code> or<code>clang</code>) performs four major stages internally:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Tool</th><th>Input</th><th>Output</th><th>Description</th></tr></thead><tbody><tr><td>1. Preprocessing</td><td><code>cpp</code></td><td><code>hello.c</code></td><td>expanded source</td><td>Handles<code>#include</code>,<code>#define</code>, and macros</td></tr><tr><td>2. Compilation</td><td><code>cc1</code></td><td>expanded source</td><td><code>hello.s</code></td><td>Translates C into assembly</td></tr><tr><td>3. Assembly</td><td><code>as</code></td><td><code>hello.s</code></td><td><code>hello.o</code></td><td>Converts assembly into machine code</td></tr><tr><td>4. Linking</td><td><code>ld</code></td><td><code>.o</code>+ libraries</td><td><code>hello</code></td><td>Combines everything into a runnable program</td></tr></tbody></table><p>You can stop at any step with compiler flags to see what’s happening.</p><h4 id="tiny-code-observe-each-stage" tabindex="-1">Tiny Code: Observe Each Stage <a class="header-anchor" href="#tiny-code-observe-each-stage" aria-label="Permalink to &quot;Tiny Code: Observe Each Stage&quot;">​</a></h4><p>Let’s use a simple program:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// hello.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, C!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run these commands to inspect each stage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1. Preprocessing</span></span>
<span class="line"><span>gcc -E hello.c -o hello.i</span></span>
<span class="line"><span># 2. Compilation to Assembly</span></span>
<span class="line"><span>gcc -S hello.i -o hello.s</span></span>
<span class="line"><span># 3. Assembly to Object File</span></span>
<span class="line"><span>gcc -c hello.s -o hello.o</span></span>
<span class="line"><span># 4. Linking</span></span>
<span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>Now check what each file looks like:</p><ul><li><code>hello.i</code>: C code with headers expanded</li><li><code>hello.s</code>: Human-readable assembly instructions</li><li><code>hello.o</code>: Machine code (binary object)</li><li><code>hello</code>: Final executable</li></ul><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C!</span></span></code></pre></div><h4 id="step-2-preprocessing-include-define-if" tabindex="-1">Step 2. Preprocessing (#include, #define, #if) <a class="header-anchor" href="#step-2-preprocessing-include-define-if" aria-label="Permalink to &quot;Step 2. Preprocessing (#include, #define, #if)&quot;">​</a></h4><p>The preprocessor handles all lines starting with<code>#</code>. It’s purely textual, no code execution yet.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E hello.c -o hello.i</span></span></code></pre></div><p>Open<code>hello.i</code> and you’ll see thousands of lines from<code>stdio.h</code> inserted into your code. It also replaces macros and removes comments.</p><p>This is the stage where your headers, macros, and conditional compilation come to life.</p><h4 id="step-3-compilation-to-assembly" tabindex="-1">Step 3. Compilation (to Assembly) <a class="header-anchor" href="#step-3-compilation-to-assembly" aria-label="Permalink to &quot;Step 3. Compilation (to Assembly)&quot;">​</a></h4><p>Next, the compiler translates your preprocessed C code into assembly language for your target CPU.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -S hello.i -o hello.s</span></span></code></pre></div><p>Open<code>hello.s</code> to peek at low-level instructions like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov     edi, OFFSET FLAT:.LC0</span></span>
<span class="line"><span>call    puts</span></span></code></pre></div><p>These are CPU-specific, on x86, ARM, or RISC-V, they’ll differ. This stage also performs optimization, type checking, and error detection.</p><h4 id="step-4-assembly-to-object-file" tabindex="-1">Step 4. Assembly (to Object File) <a class="header-anchor" href="#step-4-assembly-to-object-file" aria-label="Permalink to &quot;Step 4. Assembly (to Object File)&quot;">​</a></h4><p>The assembler converts the<code>.s</code> file into raw machine instructions and data structures, producing a relocatable object file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.s -o hello.o</span></span></code></pre></div><p>You can inspect it with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -d hello.o</span></span></code></pre></div><p>Each function in your code becomes a symbol in this object file.</p><h4 id="step-5-linking" tabindex="-1">Step 5. Linking <a class="header-anchor" href="#step-5-linking" aria-label="Permalink to &quot;Step 5. Linking&quot;">​</a></h4><p>The linker (<code>ld</code>) combines object files and libraries into a single executable.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.o -o hello</span></span></code></pre></div><p>If your program uses external functions (like<code>printf</code>), the linker locates them in system libraries (e.g.,<code>/usr/lib/libc.so</code>) and records their addresses.</p><p>The result: one self-contained executable ready to run.</p><h4 id="step-6-inspect-the-final-binary" tabindex="-1">Step 6. Inspect the Final Binary <a class="header-anchor" href="#step-6-inspect-the-final-binary" aria-label="Permalink to &quot;Step 6. Inspect the Final Binary&quot;">​</a></h4><p>Use tools like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file hello</span></span>
<span class="line"><span>nm hello | head</span></span>
<span class="line"><span>readelf -h hello</span></span></code></pre></div><p>These reveal:</p><ul><li>File type (ELF, Mach-O, etc.)</li><li>Defined and undefined symbols</li><li>Sections like<code>.text</code>,<code>.data</code>,<code>.bss</code></li></ul><p>You’re now seeing your C code at the machine level.</p><h4 id="step-7-cleanup-and-automation" tabindex="-1">Step 7. Cleanup and Automation <a class="header-anchor" href="#step-7-cleanup-and-automation" aria-label="Permalink to &quot;Step 7. Cleanup and Automation&quot;">​</a></h4><p>While it’s educational to run each step manually, most of the time you’ll rely on:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>or a<code>Makefile</code> to orchestrate multiple files (we’ll cover that in Section 55).</p><h4 id="tiny-code-multi-file-example" tabindex="-1">Tiny Code: Multi-File Example <a class="header-anchor" href="#tiny-code-multi-file-example" aria-label="Permalink to &quot;Tiny Code: Multi-File Example&quot;">​</a></h4><p>Let’s build a two-file program manually:</p><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C programmer&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>greet.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>greet.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void greet(const char *name);</span></span></code></pre></div><p>Compile and link manually:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c greet.c</span></span>
<span class="line"><span>gcc main.o greet.o -o app</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C programmer!</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Understanding the compilation pipeline helps you:</p><ul><li>Debug tricky build errors (<code>undefined reference</code>,<code>multiple definition</code>, etc.)</li><li>Control optimization and debugging symbols</li><li>Inspect intermediate stages for learning or tuning performance</li><li>Build your own lightweight build systems or compilers</li></ul><p>This is how source code becomes machine reality, step by step, precisely defined.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Generate all intermediate files (<code>.i</code>,<code>.s</code>,<code>.o</code>) for a few programs and inspect them.</li><li>Experiment with<code>gcc -O0</code>,<code>-O2</code>, and<code>-O3</code> and observe how assembly changes.</li><li>Add<code>-g</code> and explore the binary with<code>gdb</code>.</li><li>Build a program that spans multiple<code>.c</code> files.</li><li>Use<code>nm</code> and<code>objdump</code> to trace how symbols move through the stages.</li></ol><p>Next, you’ll explore the preprocessor and macros, the engine behind includes, constants, and compile-time code generation.</p>`,71)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
